/** Phrases with a number or a name in them. */
export const TH_PATTERNS: Language['patterns'] = [
  [/^(\d+) elements?$/, (m) => `${m[1]} องค์ประกอบ`],
  [/^Still working on: (.+)…$/, (m) => { const t = TH[m[1]] ?? m[1]; return `ยังทำงานอยู่: ${t}…`; }],
];
